<script setup lang="ts">
const { t } = useLanguage()
const db=useSupabase(),auth=useAuth(),summary=ref<any>(null),history=ref<any[]>([]),periods=ref<any[]>([]),error=ref(''),success=ref(''),busy=ref(false),partnerName=ref('')
const filter=reactive({partner:'',month:nowMonth(),from:'',to:''})
const staff=ref<any[]>([])
const withdrawals=computed(()=>history.value.filter(r=>r.kind==='withdrawal'&&(!filter.partner||r.partner_id===filter.partner)&&(!filter.month||r.transacted_on.startsWith(filter.month))&&(!filter.from||r.transacted_on>=filter.from)&&(!filter.to||r.transacted_on<=filter.to)))
const monthlyTotal=(id:string)=>history.value.filter(r=>r.kind==='withdrawal'&&!r.voided_at&&r.partner_id===id&&r.transacted_on.startsWith(filter.month)).reduce((sum,r)=>sum+Number(r.amount),0)
const form=reactive({partner:'',kind:'withdrawal',amount:0,date:todayKarachi(),note:''}),distribution=reactive({period:'',amount:0,reason:''}),transactionKey=useRequestKey(),distributionKey=useRequestKey()
async function load(){if(!db)return;busy.value=true;error.value='';try{const s=await db.rpc('partner_account_summary');if(s.error)throw s.error;summary.value=s.data;staff.value=await allRows(()=>db.from('staff_profiles').select('id,full_name').order('id'));[history.value,periods.value]=await Promise.all([allRows(()=>db.from('partner_transactions').select('*').order('created_at',{ascending:false}).order('id')),allRows(()=>db.from('billing_periods').select('*').in('status',['closed','locked']).order('year_month',{ascending:false}))])}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function act(action:()=>PromiseLike<any>,message:string){if(busy.value)return;busy.value=true;error.value='';try{const q=await action();if(q.error)throw q.error;success.value=message;await load()}catch(e){error.value=errText(e)}finally{busy.value=false}}
async function add(){if(!db)return;await act(()=>db.from('partners').insert({full_name:partnerName.value.trim(),ownership_units:1}),t('financialUi.partners.savedPartner'));partnerName.value=''}
async function record(){if(!db)return;await act(()=>db.rpc('record_partner_transaction',{p_partner:form.partner,p_kind:'withdrawal',p_amount:form.amount,p_date:form.date,p_note:form.note,p_request:transactionKey.forPayload(form)}),t('registration.withdrawalSaved'));if(!error.value){transactionKey.reset();form.amount=0}}
async function distribute(){if(!db||!window.confirm(t('financialUi.partners.confirmDistribution')))return;await act(()=>db.rpc('distribute_partner_profit',{p_period:distribution.period,p_total:distribution.amount,p_reason:distribution.reason,p_request:distributionKey.forPayload(distribution)}),t('financialUi.partners.distributionSaved'));if(!error.value){distributionKey.reset();distribution.amount=0}}
async function cancel(r:any){if(!db)return;const reason=window.prompt(r.batch_id?t('financialUi.partners.voidBatchPrompt'):t('financialUi.partners.voidPrompt'));if(!reason)return;await act(()=>db.rpc('void_partner_transaction',{p_id:r.id,p_reason:reason}),t('financialUi.partners.voidSaved'))}
const capital=reactive({partner:'',amount:0,date:todayKarachi(),note:''}),capitalKey=useRequestKey()
async function recordCapital(){if(!db)return;await act(()=>db.rpc('record_partner_transaction',{p_partner:capital.partner,p_kind:'capital',p_amount:capital.amount,p_date:capital.date,p_note:capital.note,p_request:capitalKey.forPayload(capital)}),t('financialUi.partners.transactionSaved'));if(!error.value){capitalKey.reset();capital.amount=0}}
onMounted(load)
</script>
<template><div><PageTitle :title="t('financialUi.partners.title')" :subtitle="t('financialUi.partners.subtitle')"><button class="btn" :disabled="busy" @click="load">{{ t('financialUi.refresh') }}</button></PageTitle><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><template v-if="summary"><section class="card"><p>{{ t('financialUi.partners.distributableReserve') }} <strong>{{money(summary.distributable_reserve)}}</strong></p><p class="hint">{{ t('financialUi.partners.reserveNote') }}</p><table class="data-table"><thead><tr><th>{{ t('financialUi.partners.partner') }}</th><th>{{ t('financialUi.partners.share') }}</th><th>{{ t('financialUi.partners.capital') }}</th><th>{{ t('financialUi.partners.withdrawal') }}</th><th>{{ t('financialUi.partners.distributedProfit') }}</th></tr></thead><tbody><tr v-for="p in summary.partners" :key="p.id"><td>{{p.full_name}}</td><td>{{p.ownership_units}} / {{p.ownership_denominator}}</td><td>{{money(p.capital)}}</td><td>{{money(p.withdrawals)}}</td><td>{{money(p.distributions)}}</td></tr></tbody></table><form v-if="auth.profile.value?.role==='admin'&&summary.partners.length<3" class="table-toolbar" @submit.prevent="add"><label>{{ t('financialUi.partners.addPartner') }}<input v-model="partnerName" required/></label><button class="btn" :disabled="busy">{{ t('financialUi.partners.addPartnerButton') }}</button></form></section><div class="grid-two" style="margin-top:20px"><section class="card"><h3>{{ t('registration.withdrawals') }}</h3><form v-if="auth.canFinance.value" @submit.prevent="record"><div class="form-grid"><label>{{ t('financialUi.partners.partner') }}<select v-model="form.partner" required><option value="">{{ t('financialUi.select') }}</option><option v-for="p in summary.partners" :key="p.id" :value="p.id">{{p.full_name}}</option></select></label><label>{{ t('financialUi.amount') }}<input v-model.number="form.amount" type="number" min="0.01" step="0.01" required/></label><label>{{ t('registration.withdrawalDate') }}<input v-model="form.date" type="date" required/></label><label class="wide">{{ t('financialUi.description') }}<textarea v-model="form.note" required/></label></div><div class="form-footer"><button class="btn primary" :disabled="busy">{{ t('registration.recordWithdrawal') }}</button></div></form></section><section v-if="auth.profile.value?.role==='admin'" class="card"><h3>{{ t('financialUi.partners.distributeProfit') }}</h3><form @submit.prevent="distribute"><label>{{ t('financialUi.teacherSettlements.closedMonth') }}<select v-model="distribution.period" required><option value="">{{ t('financialUi.selectMonth') }}</option><option v-for="p in periods" :key="p.id" :value="p.id">{{p.year_month}}</option></select></label><label>{{ t('financialUi.partners.totalThreeShares') }}<input v-model.number="distribution.amount" type="number" min="0.03" step="0.03" required/></label><label>{{ t('financialUi.partners.approvalReason') }}<textarea v-model="distribution.reason" minlength="4" required/></label><p>{{ t('financialUi.partners.shareAmount',{amount:money(distribution.amount/3)}) }}</p><div class="form-footer"><button class="btn primary" :disabled="busy||!summary.configuration_valid">{{ t('financialUi.partners.approveDistribution') }}</button></div></form></section></div><section class="card" style="margin-top:20px"><h3>{{t('registration.withdrawals')}}</h3><div class="form-grid"><label>{{t('financialUi.partners.partner')}}<select v-model="filter.partner"><option value="">{{t('registration.all')}}</option><option v-for="p in summary.partners" :key="p.id" :value="p.id">{{p.full_name}}</option></select></label><label>{{t('registration.month')}}<input v-model="filter.month" type="month"/></label><label>{{t('registration.from')}}<input v-model="filter.from" type="date"/></label><label>{{t('registration.to')}}<input v-model="filter.to" type="date" :min="filter.from"/></label></div><div class="stats-strip"><div v-for="p in summary.partners" :key="p.id" class="stat-line"><span>{{p.full_name}} ? {{t('registration.monthlyTotal')}}</span><strong>{{money(monthlyTotal(p.id))}}</strong></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t('financialUi.partners.partner')}}</th><th>{{t('registration.withdrawalDate')}}</th><th>{{t('financialUi.amount')}}</th><th>{{t('financialUi.description')}}</th><th>{{t('registration.recordedBy')}}</th><th>{{t('financialUi.status')}}</th></tr></thead><tbody><tr v-for="r in withdrawals" :key="r.id"><td>{{summary.partners.find((p:any)=>p.id===r.partner_id)?.full_name}}</td><td>{{r.transacted_on}}</td><td>{{money(r.amount)}}</td><td>{{r.description}}</td><td>{{staff.find(p=>p.id===r.entered_by)?.full_name||r.entered_by||'?'}}</td><td>{{r.voided_at?t('financialUi.expenses.voidedReason',{reason:r.void_reason}):t('financialUi.valid')}}</td></tr></tbody></table></div></section><section class="card" style="margin-top:20px"><h3>{{ t('financialUi.partners.transactionHistory') }}</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>{{ t('financialUi.partners.partner') }}</th><th>{{ t('financialUi.partners.kind') }}</th><th>{{ t('financialUi.date') }}</th><th>{{ t('financialUi.amount') }}</th><th>{{ t('financialUi.description') }}</th><th>{{ t('financialUi.status') }}</th><th>{{ t('financialUi.partners.edit') }}</th></tr></thead><tbody><tr v-for="r in history" :key="r.id"><td>{{summary.partners.find((p:any)=>p.id===r.partner_id)?.full_name}}</td><td>{{r.kind==='capital'?t('financialUi.partners.capital'):r.kind==='withdrawal'?t('financialUi.partners.withdrawal'):t('financialUi.partners.profitDistribution')}}</td><td>{{r.transacted_on}}</td><td>{{money(r.amount)}}</td><td>{{r.description}}</td><td>{{r.voided_at?t('financialUi.expenses.voidedReason',{reason:r.void_reason}):t('financialUi.valid')}}</td><td><button v-if="auth.profile.value?.role==='admin'&&!r.voided_at" class="btn small-btn danger" :disabled="busy" @click="cancel(r)">{{ t('financialUi.voidWithReason') }}</button></td></tr></tbody></table></div></section><details v-if="auth.canFinance.value" class="card" style="margin-top:20px"><summary>{{t('registration.capitalManagement')}}</summary><form @submit.prevent="recordCapital"><div class="form-grid"><label>{{t('financialUi.partners.partner')}}<select v-model="capital.partner" required><option value="">{{t('financialUi.select')}}</option><option v-for="p in summary.partners" :key="p.id" :value="p.id">{{p.full_name}}</option></select></label><label>{{t('financialUi.amount')}}<input v-model.number="capital.amount" type="number" min="0.01" step="0.01" required/></label><label>{{t('financialUi.date')}}<input v-model="capital.date" type="date" required/></label><label>{{t('financialUi.description')}}<textarea v-model="capital.note" required/></label></div><button class="btn" :disabled="busy">{{t('registration.capitalManagement')}}</button></form></details></template></div></template>
